import{_ as a,o as s,c as t,a2 as e}from"./chunks/framework.XXezeKOl.js";const u=JSON.parse('{"title":"Agent 到底是什么","description":"用一个可操作的定义拆解 AI Agent：模型、工具、循环与环境，以及它和普通 LLM 调用的本质区别。","frontmatter":{"title":"Agent 到底是什么","description":"用一个可操作的定义拆解 AI Agent：模型、工具、循环与环境，以及它和普通 LLM 调用的本质区别。"},"headers":[],"relativePath":"guide/00-intro/what-is-agent.md","filePath":"guide/00-intro/what-is-agent.md","lastUpdated":null}'),l={name:"guide/00-intro/what-is-agent.md"};function r(i,n,p,o,d,g){return s(),t("div",null,[...n[0]||(n[0]=[e(`<h1 id="agent-到底是什么" tabindex="-1">Agent 到底是什么 <a class="header-anchor" href="#agent-到底是什么" aria-label="Permalink to &quot;Agent 到底是什么&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>给出一个能指导工程实践的 Agent 定义，而不是营销口号</li><li>理解 Agent 的四个组成部分：模型、工具、循环、环境（含记忆）</li><li>能判断一个系统「是不是 Agent」以及「Agent 程度有多高」</li><li>建立后续模块的整体地图：每个模块解决 Agent 的哪一块问题</li></ul></div><h2 id="从一次-llm-调用说起" tabindex="-1">从一次 LLM 调用说起 <a class="header-anchor" href="#从一次-llm-调用说起" aria-label="Permalink to &quot;从一次 LLM 调用说起&quot;">​</a></h2><p>最简单的大模型应用是这样的：把用户问题发给模型，模型返回一段文字，结束。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题 ──▶ LLM ──▶ 回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这类应用能做很多事：翻译、总结、写邮件。但它有两个硬限制：</p><ol><li><strong>只能「说」，不能「做」</strong>。模型不知道今天的天气，不能查你的数据库，也不能帮你改代码文件。</li><li><strong>只有一步</strong>。模型一次性给出答案，没有机会根据中间结果调整做法。</li></ol><p>现在换个问题：「帮我查一下上海明天的天气，如果下雨就把我日历上下午的户外会议改到室内。」一次调用显然不够，你需要：查天气 → 读结果 → 判断 → 查日历 → 修改会议 → 汇报。哪一步做什么、做不做，取决于上一步的结果。</p><p><strong>让模型自己决定下一步做什么，并通过工具真正去做，循环直到完成任务</strong>，这就是 Agent。</p><h2 id="一个可操作的定义" tabindex="-1">一个可操作的定义 <a class="header-anchor" href="#一个可操作的定义" aria-label="Permalink to &quot;一个可操作的定义&quot;">​</a></h2><p>业界对 Agent 的定义很多，本站采用一个偏工程的版本：</p><blockquote><p>Agent 是一个以 LLM 为决策核心、能够调用工具与环境交互、并在循环中根据反馈自主决定下一步行动、直到达成目标的系统。</p></blockquote><p>Anthropic 在《Building effective agents》里给了一个类似的区分：Workflow 是「LLM 和工具按预先写好的代码路径编排」，Agent 是「LLM 动态地主导自己的流程和工具使用」。关键词是<strong>谁来决定控制流</strong>。</p><p>拆开看，一个 Agent 有四个组成部分：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌──────────────────────────────┐</span></span>
<span class="line"><span>                │            Agent             │</span></span>
<span class="line"><span>   目标/任务 ──▶ │   ┌────────┐   决定行动        │</span></span>
<span class="line"><span>                │   │  LLM   │ ───────────┐     │</span></span>
<span class="line"><span>                │   │ (大脑)  │            ▼     │</span></span>
<span class="line"><span>                │   └────────┘      ┌─────────┐ │      ┌──────────┐</span></span>
<span class="line"><span>                │       ▲           │  工具    │ ├────▶ │  环境     │</span></span>
<span class="line"><span>                │       │ 观察结果   │ (手脚)   │ │      │ API/文件/ │</span></span>
<span class="line"><span>                │       └───────────┴─────────┘ │ ◀────┤ 浏览器/DB │</span></span>
<span class="line"><span>                │   上下文 / 记忆（工作台）         │      └──────────┘</span></span>
<span class="line"><span>                └──────────────────────────────┘</span></span>
<span class="line"><span>                         ↑ 循环直到完成或触发终止条件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><table tabindex="0"><thead><tr><th>组成</th><th>作用</th><th>对应本站模块</th></tr></thead><tbody><tr><td>模型（LLM）</td><td>理解任务、推理、选择下一步行动</td><td>02 大模型原理、03 API、04 提示词</td></tr><tr><td>工具（Tools）</td><td>让模型能「做事」：查询、计算、读写、调用外部系统</td><td>05 Tool Calling、10 MCP</td></tr><tr><td>循环（Loop）</td><td>行动 → 观察 → 再决策，并在合适时停下</td><td>06 Agent 循环</td></tr><tr><td>环境与记忆</td><td>工具作用的对象，以及模型每一步能看到的信息</td><td>07 上下文工程、08 记忆、09 RAG</td></tr></tbody></table><h2 id="agent-循环的最小形态" tabindex="-1">Agent 循环的最小形态 <a class="header-anchor" href="#agent-循环的最小形态" aria-label="Permalink to &quot;Agent 循环的最小形态&quot;">​</a></h2><p>把上面的图写成伪代码，Agent 的核心只有十几行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>messages = [system_prompt, user_task]</span></span>
<span class="line"><span>for step in 1..MAX_STEPS:</span></span>
<span class="line"><span>    reply = llm(messages, tools=tool_definitions)</span></span>
<span class="line"><span>    if reply 没有请求调用工具:</span></span>
<span class="line"><span>        return reply.text            # 模型认为任务完成</span></span>
<span class="line"><span>    for call in reply.tool_calls:</span></span>
<span class="line"><span>        result = execute(call.name, call.arguments)   # 真正执行</span></span>
<span class="line"><span>        messages.append(result)      # 把观察结果喂回模型</span></span>
<span class="line"><span>return &quot;达到最大步数，停止&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>注意几件事：</p><ul><li><strong>模型并不执行工具</strong>。模型只是输出「我想调用 <code>get_weather</code>，参数是 <code>{&quot;city&quot;: &quot;上海&quot;}</code>」这样的结构化请求，真正执行的是你的代码。这也是安全控制的落点。</li><li><strong>循环是关键</strong>。没有循环，就只是「带工具的单次调用」；有了循环，模型才能根据观察结果修正计划。</li><li><strong>必须有终止条件</strong>。最大步数、Token 预算、超时，缺一不可，否则一个困惑的模型会一直调用工具烧钱。</li></ul><p>这个循环在 <a href="/guide/06-agent-loop/handwritten-agent">06 Agent 循环</a> 里会用 Python / Go / Java 完整实现一遍。</p><h2 id="agent-是一个光谱-不是开关" tabindex="-1">Agent 是一个光谱，不是开关 <a class="header-anchor" href="#agent-是一个光谱-不是开关" aria-label="Permalink to &quot;Agent 是一个光谱，不是开关&quot;">​</a></h2><p>「这个系统算不算 Agent」常常争论不休。更有用的问法是：<strong>模型在多大程度上掌控流程？</strong></p><table tabindex="0"><thead><tr><th>层级</th><th>描述</th><th>例子</th></tr></thead><tbody><tr><td>L0 单次调用</td><td>输入 → 输出，无工具</td><td>翻译、摘要</td></tr><tr><td>L1 增强型 LLM</td><td>单次调用 + 检索或一次工具调用</td><td>简单 RAG 问答</td></tr><tr><td>L2 Workflow</td><td>多步骤，但步骤顺序由代码写死</td><td>「抽取 → 校验 → 生成报告」流水线</td></tr><tr><td>L3 单 Agent</td><td>模型在循环中自主选择工具和步骤</td><td>编程助手、研究助手</td></tr><tr><td>L4 多 Agent</td><td>多个 Agent 分工协作、互相交接</td><td>规划 Agent + 执行 Agent + 审查 Agent</td></tr></tbody></table><p>层级越高，灵活性越强，但成本、延迟、不可预测性也越高。<strong>工程上的原则是：用能解决问题的最低层级</strong>。下一篇 <a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a> 会详细讨论如何选择。</p><h2 id="为什么是现在" tabindex="-1">为什么是现在 <a class="header-anchor" href="#为什么是现在" aria-label="Permalink to &quot;为什么是现在&quot;">​</a></h2><p>Agent 的思想并不新，强化学习和经典 AI 里早就有「智能体」概念。最近几年它变得可用，主要因为三件事：</p><ol><li><strong>模型推理能力提升</strong>：能可靠地理解复杂指令、拆解任务。</li><li><strong>原生 Tool Calling</strong>：主流模型 API 都支持结构化的工具调用，不再需要用正则从文本里抠参数。</li><li><strong>长上下文</strong>：模型一次能看到更多历史和工具结果，多步任务不容易「失忆」。</li></ol><p>但要清醒：Agent 依然会犯错、会幻觉、会在循环里打转。理解这些边界，是 <a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a> 的主题。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>把「接了大模型的聊天框」叫 Agent</strong>。没有工具和循环，它只是 Chatbot。概念不清会导致架构选型错误。</li><li><strong>以为模型会「自己执行」工具</strong>。工具永远由你的代码执行，权限、超时、参数校验都是你的责任。</li><li><strong>一上来就做多 Agent</strong>。大多数问题用一个设计良好的单 Agent，甚至一个 Workflow 就能解决。</li><li><strong>忽略终止条件</strong>。生产环境里没有步数和预算上限的 Agent 是事故隐患。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1. 一个系统先用 LLM 把用户问题分类，然后根据分类结果走三条写死的代码分支之一，最后再用 LLM 生成回复。它是 Agent 吗？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>按本站定义，它更接近 Workflow（L2）。虽然用了多次 LLM 调用，但控制流由代码预先决定，模型没有在循环中自主选择行动。这并不是缺点，对于路径明确的任务，Workflow 往往更稳定、更便宜。</p></details><p><strong>2. 在 Agent 循环中，模型输出了一个 Tool Call 请求，接下来由谁执行？执行结果去哪里？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>由宿主程序（你的代码）解析请求、校验参数并执行对应函数。执行结果作为一条新消息追加到对话上下文中，在下一轮发给模型，模型据此决定继续调用工具还是给出最终答案。</p></details><p><strong>3. 为什么说 Agent 必须有终止条件？列出至少两种。</strong></p><details class="details custom-block"><summary>查看答案</summary><p>模型可能误判任务未完成，或在错误路径上反复尝试，导致无限循环、成本失控。常见终止条件：最大步数、Token 或费用预算、总超时时间、连续错误次数上限，以及需要人工确认的高风险操作。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic: Building effective agents</a></li><li><a href="https://lilianweng.github.io/posts/2023-06-23-agent/" target="_blank" rel="noreferrer">Lilian Weng: LLM Powered Autonomous Agents</a></li><li><a href="/papers/react">ReAct 论文解读</a></li><li>本站：<a href="/guide/05-tool-calling/concept">工具调用原理</a>、<a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a></li></ul>`,41)])])}const h=a(l,[["render",r]]);export{u as __pageData,h as default};
